//! Rescyo's desktop interface.
//!
//! Our code contains no `unsafe` (`deny` from the workspace). The one exception is the code the
//! Slint compiler generates from `ui/*.slint`, which allows it internally for its vtables; it
//! is isolated in [`generated`].
#![deny(unsafe_code)]

mod generated {
    #![allow(unsafe_code, reason = "code generated by the Slint compiler")]
    #![allow(clippy::all, clippy::pedantic, missing_debug_implementations, reason = "generated code")]
    slint::include_modules!();
}

pub use generated::*;

#[cfg(test)]
mod tests;
